MOTIF_NAME = 'stm_pawn_island_advantage'
MOTIF_DESCRIPTION = 'The side to move has fewer pawn-island groups (maximal sets of pawns on contiguous files) than the opponent, indicating a more cohesive pawn structure.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    def islands(color):
        pawns = b.pieces(chess.PAWN, color)
        if not pawns:
            return 0
        files = sorted({chess.square_file(p) for p in pawns})
        cnt = 1
        for i in range(1, len(files)):
            if files[i] > files[i-1] + 1:
                cnt += 1
        return cnt
    return islands(stm) < islands(opp)

MOTIF_NAME = 'stm_central_piece_value_lead'
MOTIF_DESCRIPTION = 'The side to move has at least two more total piece value on the central 4x4 box (files c through f, ranks 3 through 6) than the opponent.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 0}
    sp = 0
    op = 0
    for f in (2, 3, 4, 5):
        for r in (2, 3, 4, 5):
            p = b.piece_at(chess.square(f, r))
            if p is None:
                continue
            if p.color == stm:
                sp += vals[p.piece_type]
            else:
                op += vals[p.piece_type]
    return sp >= op + 2

MOTIF_NAME = 'stm_development_edge_advantage'
MOTIF_DESCRIPTION = 'The side to move has strictly fewer undeveloped (back-rank) knights or bishops than the opponent, indicating superior piece development and initiative.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    stm_back = 0 if stm == chess.WHITE else 7
    opp_back = 7 if stm == chess.WHITE else 0
    def back_minor_cnt(color, back):
        cnt = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in b.pieces(pt, color):
                if chess.square_rank(sq) == back:
                    cnt += 1
        return cnt
    return back_minor_cnt(stm, stm_back) < back_minor_cnt(opp, opp_back)

MOTIF_NAME = 'stm_central_pawn_density_pressure_advantage'
MOTIF_DESCRIPTION = (
    'The side to move has more pawns and pieces on files c through f within '
    'its attack zone than the opponent has on the corresponding files, '
    'indicating central pressure and space, with a non-pawn attacker of the centre.'
)

import chess


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    if not b.is_valid():
        return False
    stm = b.turn
    opp = not stm
    CENTRAL = [2, 3, 4, 5]
    white_attack = [0, 1, 2, 3]
    black_attack = [4, 5, 6, 7]

    def _central_value(color: bool) -> int:
        val = 0
        attack_ranks = white_attack if color else black_attack
        for f in CENTRAL:
            for r in attack_ranks:
                p = b.piece_at(chess.square(f, r))
                if p and p.color == color:
                    if p.piece_type == chess.PAWN:
                        val += 1
                    elif p.piece_type in (chess.KNIGHT, chess.BISHOP):
                        val += 3
                    elif p.piece_type == chess.ROOK:
                        val += 5
                    elif p.piece_type == chess.QUEEN:
                        val += 9
        return val

    vstm = _central_value(stm)
    vopp = _central_value(opp)
    if vstm <= 4 or vstm <= vopp:
        return False
    if vstm - vopp < 5:
        return False

    def _attacks_centre_with_nonpawn(color: bool) -> bool:
        targets = [chess.square(f, r) for f in CENTRAL for r in (3, 4)]
        for sq in targets:
            for a in b.attackers(color, sq):
                p = b.piece_at(a)
                if p and p.color == color and p.piece_type != chess.PAWN and p.piece_type != chess.KING:
                    return True
        return False

    return _attacks_centre_with_nonpawn(stm)

MOTIF_NAME = 'stm_dual_check_sources'
MOTIF_DESCRIPTION = 'The side to move has legal checking moves from at least two different pieces, indicating coordinated pressure on the opponent king.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    sources = set()
    for mv in b.legal_moves:
        if b.gives_check(mv):
            sources.add(mv.from_square)
            if len(sources) >= 2:
                return True
    return False

MOTIF_NAME = 'stm_king_pawn_shield_advantage'
MOTIF_DESCRIPTION = 'The side to move has a complete pawn shield in front of its back-rank king while the opponent king lacks such a shield.'

import chess

def motif(fen: str) -> bool:
    b = chess.Board(fen)
    if b.is_check():
        return False
    stm = b.turn
    opp = not stm

    def shielded(color):
        k = b.king(color)
        if k is None:
            return False
        f = chess.square_file(k)
        r = chess.square_rank(k)
        if color == chess.WHITE and r != 0:
            return False
        if color == chess.BLACK and r != 7:
            return False
        fr = 1 if color == chess.WHITE else 6
        pawns = b.pieces(chess.PAWN, color)
        lo = max(0, f - 1)
        hi = min(7, f + 1)
        for df in range(lo, hi + 1):
            if chess.square(df, fr) not in pawns:
                return False
        return True

    return shielded(stm) and not shielded(opp)

MOTIF_NAME = 'stm_royal_fork_check_targets_major_piece'
MOTIF_DESCRIPTION = 'The side to move has a legal checking move that either captures an enemy rook or queen or, after the move, attacks an enemy rook or queen with the moved piece.'
def motif(fen: str) -> bool:
    b = chess.Board(fen)
    opp = not b.turn
    for move in b.legal_moves:
        cap = b.piece_at(move.to_square)
        if cap is not None and cap.color == opp and cap.piece_type in (chess.ROOK, chess.QUEEN):
            if b.gives_check(move):
                return True
        if not b.gives_check(move):
            continue
        t = move.to_square
        if b.piece_at(move.from_square) is None:
            continue
        b.push(move)
        ok = False
        pt = b.piece_at(t)
        if pt is not None:
            for s in b.attacks(t):
                p2 = b.piece_at(s)
                if p2 is not None and p2.color == opp and p2.piece_type in (chess.ROOK, chess.QUEEN):
                    ok = True
                    break
        b.pop()
        if ok:
            return True
    return False

MOTIF_NAME = 'stm_nonpawn_king_zone_attack_ratio'
MOTIF_DESCRIPTION = 'The side to move has at least two non-pawn pieces attacking the opponent king\'s 3x3 zone while the opponent has at most one non-pawn piece attacking the side-to-move king\'s 3x3 zone.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    def nonpawn_zone_attackers(attacker_color, king_color):
        ksq = b.king(king_color)
        if ksq is None:
            return 0
        kf = chess.square_file(ksq)
        kr = chess.square_rank(ksq)
        seen = set()
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f = kf + df
                r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    for sq in b.attackers(attacker_color, chess.square(f, r)):
                        p = b.piece_at(sq)
                        if p and p.piece_type != chess.PAWN and p.piece_type != chess.KING:
                            seen.add(sq)
        return len(seen)
    return nonpawn_zone_attackers(stm, opp) >= 2 and nonpawn_zone_attackers(opp, stm) <= 1

