MOTIF_NAME = 'stm_favorable_trade_capture'
MOTIF_DESCRIPTION = 'The side to move has a legal capture of an enemy non-pawn piece that wins at least two points of material in the exchange or is undefended, bringing the static material balance to at least even.'

def motif(fen: str) -> bool:
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    imb = 0
    for pt, v in vals.items():
        imb += v * len(b.pieces(pt, stm)) - v * len(b.pieces(pt, opp))
    for move in b.legal_moves:
        if b.is_en_passant(move):
            continue
        if not b.is_capture(move):
            continue
        cap = b.piece_type_at(move.to_square)
        if cap is None or cap == chess.KING or cap == chess.PAWN:
            continue
        atk = b.piece_type_at(move.from_square)
        if atk is None or atk == chess.KING:
            continue
        cv = vals[cap]
        av = vals[atk]
        gain = cv - av
        if gain >= 2 and imb + gain >= 0:
            return True
        if not b.attackers(opp, move.to_square) and cv >= 3 and imb + cv >= 0:
            return True
    return False

MOTIF_NAME = 'stm_supported_minor_attacks_opp_king_zone'
MOTIF_DESCRIPTION = 'The side to move has a knight or bishop that is defended by a friendly pawn and that attacks a square adjacent to the opponent king, indicating a stable outpost applying pressure near the enemy king.'

def motif(fen: str) -> bool:
    b = chess.Board(fen)
    stm = b.turn
    opp_king = None
    for sq in range(64):
        p = b.piece_at(sq)
        if p and p.piece_type == chess.KING and p.color != stm:
            opp_king = sq
            break
    if opp_king is None:
        return False
    kf = chess.square_file(opp_king)
    kr = chess.square_rank(opp_king)
    zone = set()
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf, nr = kf + df, kr + dr
            if 0 <= nf < 8 and 0 <= nr < 8:
                zone.add(chess.square(nf, nr))
    for pt in (chess.KNIGHT, chess.BISHOP):
        for sq in b.pieces(pt, stm):
            has_pawn = False
            for a in b.attackers(stm, sq):
                ap = b.piece_at(a)
                if ap and ap.piece_type == chess.PAWN:
                    has_pawn = True
                    break
            if not has_pawn:
                continue
            for t in b.attacks(sq):
                if t in zone:
                    return True
    return False

MOTIF_NAME = 'stm_central_pawn_phalanx_advantage'
MOTIF_DESCRIPTION = 'The side to move has a more advanced pair of friendly pawns on adjacent central files (c-d, d-e, or e-f) than any such opponent pawn phalanx, indicating central tension and space control.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    def best_phalanx(color):
        by_rank = [set() for _ in range(8)]
        for sq in b.pieces(chess.PAWN, color):
            by_rank[chess.square_rank(sq)].add(chess.square_file(sq))
        best = 0
        for f in (2, 3, 4):
            for r in range(8):
                if f in by_rank[r] and (f + 1) in by_rank[r]:
                    adv = r if color == chess.WHITE else 7 - r
                    if adv > best:
                        best = adv
        return best
    stm_best = best_phalanx(stm)
    opp_best = best_phalanx(opp)
    return stm_best >= 3 and stm_best > opp_best

MOTIF_NAME = 'stm_attacks_hanging_opp_king_neighbor'
MOTIF_DESCRIPTION = 'The side to move has at least one legal, non-sacrificial check or capture on a square adjacent to the opponent king.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    VAL = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}
    oksq = b.king(opp)
    if oksq is None:
        return False
    king_file = chess.square_file(oksq)
    king_rank = chess.square_rank(oksq)
    neighbors = []
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = king_file + df
            nr = king_rank + dr
            if 0 <= nf < 8 and 0 <= nr < 8:
                neighbors.append(chess.square(nf, nr))
    opp_attackers_total = 0
    for n in neighbors:
        opp_attackers_total += len(b.attackers(opp, n))
    for mv in b.legal_moves:
        to = mv.to_square
        atk = b.piece_at(mv.from_square)
        if atk is None or atk.piece_type == chess.KING:
            continue
        if to not in neighbors:
            continue
        av = VAL[atk.piece_type]
        capture = b.is_capture(mv)
        dest_defended = bool(b.attackers(opp, to))
        safe = True
        consumed = set()
        # roughly safe if undefended target is a pawn and attacker value <= 3, or target value+2 >= attacker value, or square undefended by non-pawn
        if capture:
            tp = b.piece_at(to)
            if tp is not None:
                tv = VAL.get(tp.piece_type, 0)
                if dest_defended and av > tv:
                    # sacrifice unless a friendly non-pawn can recapture cheaply by value
                    rcok = False
                    ra_count = 0
                    for r in b.attackers(stm, to):
                        rp = b.piece_at(r)
                        if rp is None or r == mv.from_square:
                            continue
                        if rp.piece_type != chess.KING and VAL[rp.piece_type] <= av:
                            rcok = True
                            break
                        ra_count += 1
                    if not rcok:
                        safe = False
            elif dest_defended:
                safe = False
        else:
            if dest_defended:
                # quiet move to defended king-neighbor square is risky unless cheap piece
                if av >= 3:
                    safe = False
        if safe:
            return True
    return False

MOTIF_NAME = 'stm_attacks_opp_strong_piece_asymmetry'
MOTIF_DESCRIPTION = 'The side to move has at least one safe attack by a non-pawn piece on an enemy non-pawn piece while the opponent has no safe non-pawn attack on the side-to-move non-pawn pieces.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    PV = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}

    def nonpawns(color):
        return (b.pieces(chess.KNIGHT, color) | b.pieces(chess.BISHOP, color) |
                b.pieces(chess.ROOK, color) | b.pieces(chess.QUEEN, color))

    def has_safe_attack(attacker_color, target_color):
        for sq in nonpawns(target_color):
            atks = b.attackers(attacker_color, sq)
            if not atks:
                continue
            amin = min(PV[b.piece_at(a).piece_type] for a in atks if b.piece_at(a))
            att = min(PV[b.piece_at(a).piece_type] for a in atks if b.piece_at(a))
            ds = [PV[b.piece_at(d).piece_type] for d in b.attackers(target_color, sq) if b.piece_at(d)]
            if att <= amin and att <= PV[b.piece_at(sq).piece_type] and (not ds or min(ds) > att):
                return True
        return False

    return has_safe_attack(stm, opp) and not has_safe_attack(opp, stm)

MOTIF_NAME = 'stm_central_knight_outpost'
MOTIF_DESCRIPTION = 'The side to move has a knight on a central square (files c-f, ranks 4-5) defended by a friendly pawn and not attackable by any enemy pawn.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    dir_up = 1 if stm else -1
    for ksq in b.pieces(chess.KNIGHT, stm):
        f, r = chess.square_file(ksq), chess.square_rank(ksq)
        if not (2 <= f <= 5 and 3 <= r <= 4):
            continue
        supported = False
        for df in (-1, 1):
            nf, nr = f + df, r - dir_up
            if 0 <= nf < 8 and 0 <= nr < 8:
                p = b.piece_at(chess.square(nf, nr))
                if p and p.color == stm and p.piece_type == chess.PAWN:
                    supported = True
                    break
        if not supported:
            continue
        attacked = False
        for df in (-1, 1):
            nf, nr = f + df, r + dir_up
            if 0 <= nf < 8 and 0 <= nr < 8:
                p = b.piece_at(chess.square(nf, nr))
                if p and p.color == opp and p.piece_type == chess.PAWN:
                    attacked = True
                    break
        if not attacked:
            return True
    return False

MOTIF_NAME = 'stm_rook_uncontested_on_halfopen_file'
MOTIF_DESCRIPTION = 'The side to move has a rook on a file with no friendly pawns where the opponent has no rook or queen on that file.'
import chess

def motif(fen: str) -> bool:
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    for f in range(8):
        stm_pawn_here = False
        for r in range(8):
            sq = chess.square(f, r)
            p = b.piece_at(sq)
            if p is not None and p.piece_type == chess.PAWN and p.color == stm:
                stm_pawn_here = True
                break
        if stm_pawn_here:
            continue
        stm_has_rook = False
        opp_has_major = False
        for r in range(8):
            sq = chess.square(f, r)
            p = b.piece_at(sq)
            if p is None:
                continue
            if p.color == stm and p.piece_type == chess.ROOK:
                stm_has_rook = True
            elif p.color == opp and p.piece_type in (chess.ROOK, chess.QUEEN):
                opp_has_major = True
        if stm_has_rook and not opp_has_major:
            return True
    return False

import chess

MOTIF_NAME = 'stm_backward_pawn_advantage'
MOTIF_DESCRIPTION = 'The side to move has no backward pawns while the opponent has at least one backward pawn.'

def motif(fen: str) -> bool:
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm

    def has_backward(color):
        r_dir = 1 if color == chess.WHITE else -1
        for sq in list(b.pieces(chess.PAWN, color)):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            ar = r + r_dir
            if not 0 <= ar < 8:
                continue
            advance_sq = chess.square(f, ar)
            if b.piece_at(advance_sq) is not None:
                continue
            enemy_pawn_controls = False
            for nf in (f - 1, f + 1):
                if 0 <= nf < 8 and 0 <= ar + r_dir < 8:
                    ep = b.piece_at(chess.square(nf, ar + r_dir))
                    if ep and ep.color != color and ep.piece_type == chess.PAWN:
                        enemy_pawn_controls = True
                        break
            if not enemy_pawn_controls:
                continue
            has_neighbor = False
            backward = True
            for nf in (f - 1, f + 1):
                if 0 <= nf < 8:
                    for nsq in list(b.pieces(chess.PAWN, color)):
                        if chess.square_file(nsq) == nf:
                            has_neighbor = True
                            nr = chess.square_rank(nsq)
                            if color == chess.WHITE and nr <= r:
                                backward = False
                            if color == chess.BLACK and nr >= r:
                                backward = False
            if has_neighbor and backward:
                return True
        return False

    return not has_backward(stm) and has_backward(opp)

MOTIF_NAME = 'stm_active_major_in_opp_back_two_ranks'
MOTIF_DESCRIPTION = "The side to move has a rook or queen in the opponent's back two ranks attacking an enemy pawn while the opponent has no rook or queen in the side-to-move's back two ranks attacking side-to-move pawns."
def motif(fen: str) -> bool:
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    if stm == chess.WHITE:
        stm_ranks = {5, 6}
        opp_ranks = {1, 2}
    else:
        stm_ranks = {1, 2}
        opp_ranks = {5, 6}
    def active_major_in_ranks(color, enemy_color, ranks):
        ep = set(b.pieces(chess.PAWN, enemy_color))
        for ptype in (chess.ROOK, chess.QUEEN):
            for sq in b.pieces(ptype, color):
                if chess.square_rank(sq) in ranks:
                    for t in b.attacks(sq):
                        if t in ep:
                            return True
        return False
    return (active_major_in_ranks(stm, opp, stm_ranks) and
            not active_major_in_ranks(opp, stm, opp_ranks))
